using System;using System.Collections.ObjectModel;using System.ComponentModel;using System.IO;using System.Linq;using System.Runtime.CompilerServices;using System.Text;using System.Threading.Tasks;using System.Windows;using System.Windows.Threading;using Microsoft.Win32;using SOACS.Arsenal.Models;using SOACS.Arsenal.Services;
namespace SOACS.Arsenal
{
 public partial class MainWindow:Window,INotifyPropertyChanged
 {
  readonly ApplicationRuleService _ruleService=new ApplicationRuleService();readonly PatchScanner _scanner;readonly InstallEngine _installer=new InstallEngine();readonly MachineQualificationService _qualifier=new MachineQualificationService();readonly FirmwareValidator _firmwareValidator=new FirmwareValidator();readonly DispatcherTimer _clock=new DispatcherTimer();readonly DeploymentPackageBuilder _deploymentBuilder=new DeploymentPackageBuilder();bool _stopRequested;MachineQualification _qualification;string _repo="No repository selected",_clockText,_current="Waiting for repository selection",_status="Ready",_summary="Select the folder containing this month's updates, then scan the repository.",_qualificationStatus="Not assessed",_qualificationDetails="Run machine qualification before any firmware update.",_deploymentStatus="Scan a repository, then build a standalone PowerShell deployment package.";string _lastDeploymentPackage;int _overall;
  public ObservableCollection<PatchItem>Patches{get;}=new ObservableCollection<PatchItem>();public ObservableCollection<PatchItem>ManualPatches{get;}=new ObservableCollection<PatchItem>();public ObservableCollection<PatchItem>FirmwarePatches{get;}=new ObservableCollection<PatchItem>();public ObservableCollection<string>EventLog{get;}=new ObservableCollection<string>();public ObservableCollection<string>DeploymentBuildLog{get;}=new ObservableCollection<string>();public PatchItem SelectedPatch{get;set;}
  public string RepositoryPath{get=>_repo;set{_repo=value;Changed();}}public string ClockText{get=>_clockText;set{_clockText=value;Changed();}}public string CurrentActivity{get=>_current;set{_current=value;Changed();}}public string StatusBarText{get=>_status;set{_status=value;Changed();}}public string SummaryText{get=>_summary;set{_summary=value;Changed();}}public string QualificationStatus{get=>_qualificationStatus;set{_qualificationStatus=value;Changed();}}public string QualificationDetails{get=>_qualificationDetails;set{_qualificationDetails=value;Changed();}}public string DeploymentStatus{get=>_deploymentStatus;set{_deploymentStatus=value;Changed();}}public int OverallProgress{get=>_overall;set{_overall=value;Changed();Changed("OverallProgressText");}}public string OverallProgressText=>OverallProgress+"%";int _deploymentProgress;string _deploymentPhase="Ready",_deploymentCurrentFile="",_deploymentStats="No deployment build is currently running.";bool _deploymentBusy;public int DeploymentProgress{get=>_deploymentProgress;set{_deploymentProgress=value;Changed();Changed("DeploymentProgressText");}}public string DeploymentProgressText=>DeploymentProgress+"%";public string DeploymentPhase{get=>_deploymentPhase;set{_deploymentPhase=value;Changed();}}public string DeploymentCurrentFile{get=>_deploymentCurrentFile;set{_deploymentCurrentFile=value;Changed();}}public string DeploymentStats{get=>_deploymentStats;set{_deploymentStats=value;Changed();}}public bool DeploymentBusy{get=>_deploymentBusy;set{_deploymentBusy=value;Changed();}}
  public int FoundCount=>Patches.Count;public int CompletedCount=>Patches.Count(x=>x.Status=="Completed");public int FailedCount=>Patches.Count(x=>x.Status=="Failed"||x.Status=="Blocked");public int ManualCount=>Patches.Count(x=>x.Status=="Manual");public int RebootCount=>Patches.Count(x=>x.Status=="Reboot Required");
  public MainWindow(){_scanner=new PatchScanner(_ruleService);InitializeComponent();DataContext=this;_clock.Interval=TimeSpan.FromSeconds(1);_clock.Tick+=(s,e)=>ClockText=DateTime.Now.ToString("HH:mm:ss");_clock.Start();Log("SOACS Arsenal v1.5.3 Alpha initialized. Rules: "+_ruleService.RulesPath);var args=Environment.GetCommandLineArgs();for(int i=0;i<args.Length-1;i++){if(string.Equals(args[i],"--repository",StringComparison.OrdinalIgnoreCase)&&Directory.Exists(args[i+1])){RepositoryPath=args[i+1];CurrentActivity="Deployment repository loaded: "+RepositoryPath;Loaded+=(sender,e)=>Scan_Click(null,null);break;}}}
  void Browse_Click(object s,RoutedEventArgs e){using(var d=new System.Windows.Forms.FolderBrowserDialog()){d.Description="Select the monthly patch repository";d.ShowNewFolderButton=false;if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){RepositoryPath=d.SelectedPath;CurrentActivity="Ready to scan "+RepositoryPath;Log("Repository selected: "+RepositoryPath);}}}
  void Scan_Click(object s,RoutedEventArgs e){if(!Directory.Exists(RepositoryPath)){MessageBox.Show("Select a valid patch repository first.","SOACS Arsenal",MessageBoxButton.OK,MessageBoxImage.Warning);return;}Patches.Clear();ManualPatches.Clear();FirmwarePatches.Clear();OverallProgress=0;CurrentActivity="Scanning and building dependency plan...";foreach(var p in _scanner.Scan(RepositoryPath)){Patches.Add(p);if(!p.CanAutomate)ManualPatches.Add(p);if(p.Category=="BIOS / Firmware")FirmwarePatches.Add(p);}ValidateFirmware();Refresh();SummaryText=FoundCount+" packages found. "+(FoundCount-ManualCount)+" are planned for automation; "+ManualCount+" require manual review. Firmware is placed at the end of the plan.";CurrentActivity="Repository scan and install plan complete";StatusBarText=SummaryText;Log(SummaryText);}
  void Qualify_Click(object s,RoutedEventArgs e){CurrentActivity="Assessing system for firmware readiness...";_qualification=_qualifier.Assess();QualificationStatus=_qualification.OverallStatus;QualificationDetails=(_qualification.Manufacturer??"Unknown")+" "+(_qualification.Model??"")+" | BIOS "+(_qualification.BiosVersion??"Unknown")+" | "+_qualification.Details;ValidateFirmware();CurrentActivity="Machine qualification complete";Log(QualificationStatus+": "+QualificationDetails);}
  void ValidateFirmware(){foreach(var p in FirmwarePatches){if(p.HashStatus=="Mismatch"||p.HashStatus=="Invalid Manifest"){p.CanAutomate=false;p.Status="Blocked";p.Result="INSTALL BLOCKED: firmware hash validation failed ("+p.HashStatus+")";continue;}string reason;if(_firmwareValidator.Validate(p,_qualification,out reason)){p.Status="Approval Required";p.Result=reason+(p.HashStatus=="Verified"?" | SHA-256 verified":" | No hash supplied");}else{p.Status="Blocked";p.Result=reason;}}Refresh();}
  async void InstallAll_Click(object s,RoutedEventArgs e){var queue=Patches.Where(x=>x.CanAutomate&&(x.Status=="Queued"||x.Status=="Failed"||x.Status=="Reboot Required"||x.Status=="Approval Required")).OrderBy(x=>x.Sequence).ToList();if(queue.Count==0){MessageBox.Show("No automatic packages are queued.","SOACS Arsenal");return;}if(MessageBox.Show("Arsenal will execute "+queue.Count+" packages in the displayed dependency order. Continue?","Confirm Installation",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;_stopRequested=false;int done=0;foreach(var p in queue){if(_stopRequested)break;if(p.Category=="BIOS / Firmware"){string reason;if(!_firmwareValidator.Validate(p,_qualification,out reason)){p.Status="Blocked";p.Result=reason;Log(p.FileName+": blocked - "+reason);continue;}var answer=MessageBox.Show("FIRMWARE APPROVAL\n\nComputer: "+_qualification.Manufacturer+" "+_qualification.Model+"\nCurrent BIOS: "+_qualification.BiosVersion+"\nPackage: "+p.FileName+"\n\nConfirm this package is intended for this exact model. AC power must remain connected. Continue?","SOACS Arsenal Firmware Approval",MessageBoxButton.YesNo,MessageBoxImage.Exclamation);if(answer!=MessageBoxResult.Yes){p.Status="Manual";p.Result="Operator declined firmware execution";if(!ManualPatches.Contains(p))ManualPatches.Add(p);continue;}}
    p.Status="Installing";p.Result="Installer running";CurrentActivity="Installing "+p.FileName;Log(CurrentActivity);try{int code=await _installer.InstallAsync(p);if(code==0){p.Status="Completed";p.Result="Installed successfully (exit 0)";}else if(code==1641||code==3010){p.Status="Reboot Required";p.Result="Installed; reboot required (exit "+code+")";}else{p.Status="Failed";p.Result="Installer exit code "+code;}}catch(Exception ex){p.Status="Failed";p.Result=ex.Message;}done++;p.Progress=100;OverallProgress=(int)Math.Round(done*100.0/queue.Count);Log(p.FileName+": "+p.Status+" - "+p.Result);Refresh();}
   CurrentActivity=_stopRequested?"Installation stopped after current package":"Planned installation pass complete";SummaryText=CompletedCount+" completed, "+FailedCount+" failed/blocked, "+RebootCount+" require reboot, "+ManualCount+" require manual action.";StatusBarText=SummaryText;Log(SummaryText);}
  void Stop_Click(object s,RoutedEventArgs e){_stopRequested=true;StatusBarText="Stop requested; current installer will finish";Log(StatusBarText);}void Export_Click(object s,RoutedEventArgs e){if(Patches.Count==0)return;var d=new SaveFileDialog{Filter="CSV report (*.csv)|*.csv",FileName="SOACS_Arsenal_Report_"+DateTime.Now.ToString("yyyyMMdd_HHmm")+".csv"};if(d.ShowDialog()==true){var b=new StringBuilder();b.AppendLine("Sequence,Category,Package,Publisher,Product,Version,Rule,HashStatus,ExpectedSHA256,CalculatedSHA256,Status,Result,Path");foreach(var p in Patches)b.AppendLine(p.Sequence+","+Csv(p.Category)+","+Csv(p.FileName)+","+Csv(p.Publisher)+","+Csv(p.ProductName)+","+Csv(p.FileVersion)+","+Csv(p.RuleName)+","+Csv(p.HashStatus)+","+Csv(p.ExpectedHash)+","+Csv(p.CalculatedHash)+","+Csv(p.Status)+","+Csv(p.Result)+","+Csv(p.FullPath));File.WriteAllText(d.FileName,b.ToString());Log("Report exported: "+d.FileName);}}static string Csv(string v)=>"\""+(v??"").Replace("\"","\"\"")+"\"";
  void TeachSelected_Click(object s,RoutedEventArgs e){var p=SelectedPatch;if(p==null||p.Extension!=".exe"){MessageBox.Show("Select an unknown EXE in the Install Plan or Manual Review first.","Teach Arsenal",MessageBoxButton.OK,MessageBoxImage.Information);return;}var w=new TeachRuleWindow(p){Owner=this};if(w.ShowDialog()==true){try{_ruleService.SaveRule(w.Rule);Log("Application rule saved: "+w.Rule.Name);MessageBox.Show("Rule saved. Arsenal will rescan the repository now.","Teach Arsenal",MessageBoxButton.OK,MessageBoxImage.Information);Scan_Click(null,null);}catch(Exception ex){MessageBox.Show("Unable to save rule: "+ex.Message,"Teach Arsenal",MessageBoxButton.OK,MessageBoxImage.Error);}}}
  void OpenRules_Click(object s,RoutedEventArgs e){try{System.Diagnostics.Process.Start("explorer.exe","/select,\""+_ruleService.RulesPath+"\"");}catch(Exception ex){MessageBox.Show(ex.Message);}}
  async void BuildDeployment_Click(object s,RoutedEventArgs e){if(DeploymentBusy)return;if(!Directory.Exists(RepositoryPath)){MessageBox.Show("Select and scan a valid patch repository first.","Deployment Package",MessageBoxButton.OK,MessageBoxImage.Warning);return;}using(var d=new System.Windows.Forms.FolderBrowserDialog()){d.Description="Select a destination OUTSIDE the patch repository";d.ShowNewFolderButton=true;if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;try{DeploymentBusy=true;DeploymentBuildLog.Clear();DeploymentProgress=0;DeploymentPhase="Preparing";DeploymentCurrentFile="";DeploymentStats="Starting deployment package build...";DeploymentStatus="Building deployment package...";CurrentActivity=DeploymentStatus;StatusBarText=DeploymentStatus;DeploymentBuildLog.Add("Starting deployment package build");var progress=new Progress<DeploymentBuildProgress>(p=>{DeploymentProgress=p.Percent;DeploymentPhase=p.Phase??"Working";DeploymentCurrentFile=p.CurrentFile??"";DeploymentStatus=p.Message??DeploymentPhase;StatusBarText=DeploymentStatus;DeploymentStats=FormatDeploymentStats(p);var line=(p.Percent.ToString().PadLeft(3)+"%  "+DeploymentPhase+"  "+DeploymentStatus+(string.IsNullOrWhiteSpace(DeploymentCurrentFile)?"":"  ["+DeploymentCurrentFile+"]"));if(DeploymentBuildLog.Count==0||DeploymentBuildLog[0]!=line)DeploymentBuildLog.Insert(0,line);while(DeploymentBuildLog.Count>250)DeploymentBuildLog.RemoveAt(DeploymentBuildLog.Count-1);});var result=await Task.Run(()=>_deploymentBuilder.Build(RepositoryPath,d.SelectedPath,Patches.ToList(),progress));_lastDeploymentPackage=result.ZipPath;DeploymentProgress=100;DeploymentPhase="Complete";DeploymentCurrentFile=result.ZipPath;DeploymentStats="Deployment ID: "+result.DeploymentId+" | Repository files: "+result.RepositoryFileCount+" | ZIP size: "+FormatBytes(result.ZipSizeBytes);DeploymentStatus="Deployment ready: "+result.RepositoryFileCount+" repository files. ZIP: "+result.ZipPath;CurrentActivity="Deployment package complete";StatusBarText=DeploymentStatus;DeploymentBuildLog.Insert(0,"100%  COMPLETE  ZIP created and verified: "+result.ZipPath);Log(DeploymentStatus);MessageBox.Show("Deployment ZIP created successfully.\n\nDeployment ID:\n"+result.DeploymentId+"\n\nZIP:\n"+result.ZipPath+"\n\nThe temporary staging folder was removed.","SOACS Arsenal Deployment",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){DeploymentPhase="Failed";DeploymentStatus="Deployment build failed: "+ex.Message;DeploymentStats=DeploymentStatus;StatusBarText=DeploymentStatus;DeploymentBuildLog.Insert(0,"FAILED  "+ex.Message);Log(DeploymentStatus);MessageBox.Show(DeploymentStatus,"Deployment Package",MessageBoxButton.OK,MessageBoxImage.Error);}finally{DeploymentBusy=false;}}}string FormatDeploymentStats(DeploymentBuildProgress p){var size=p.TotalBytes>0?FormatBytes(p.BytesProcessed)+" / "+FormatBytes(p.TotalBytes):"Calculating...";var files=p.TotalFiles>0?p.FilesProcessed+" / "+p.TotalFiles+" files":"";return (string.IsNullOrWhiteSpace(files)?size:files+" | "+size);}static string FormatBytes(long value){string[] units={"B","KB","MB","GB","TB"};double n=value;int i=0;while(n>=1024&&i<units.Length-1){n/=1024;i++;}return n.ToString(i==0?"0":"0.0")+" "+units[i];}
  void OpenDeployment_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(_lastDeploymentPackage)||!File.Exists(_lastDeploymentPackage)){MessageBox.Show("No deployment ZIP has been created during this session.","Deployment Package",MessageBoxButton.OK,MessageBoxImage.Information);return;}try{System.Diagnostics.Process.Start("explorer.exe","/select,\""+_lastDeploymentPackage+"\"");}catch(Exception ex){MessageBox.Show(ex.Message);}}
  void ClearLog_Click(object s,RoutedEventArgs e){EventLog.Clear();}void About_Click(object s,RoutedEventArgs e){MessageBox.Show("SOACS Arsenal v1.5.3 Alpha\n\nOffline deployment packaging, application intelligence, Teach Arsenal rules, SHA-256 package validation, dependency-aware orchestration, all-user Store provisioning, and guarded firmware handling.","About SOACS Arsenal",MessageBoxButton.OK,MessageBoxImage.Information);}void Log(string t){EventLog.Insert(0,DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+"  "+t);while(EventLog.Count>500)EventLog.RemoveAt(EventLog.Count-1);}void Refresh(){Changed("FoundCount");Changed("CompletedCount");Changed("FailedCount");Changed("ManualCount");Changed("RebootCount");}public event PropertyChangedEventHandler PropertyChanged;void Changed([CallerMemberName]string n=null)=>PropertyChanged?.Invoke(this,new PropertyChangedEventArgs(n));
 }
